// Generates app/src/export/genankiSql.ts from genanki 0.13.1's literal
// collection schema and defaults frozen by tools/golden.py.
// Run: node app/scripts/gen-genanki.ts
import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

const root = new URL("../../", import.meta.url);
const read = (name: string) =>
  readFileSync(new URL(`tests/fixtures/synthetic/golden/apkg/${name}`, root), "utf8").replaceAll("\r\n", "\n");
const output = `// Generated by app/scripts/gen-genanki.ts from genanki 0.13.1 (APKG_SCHEMA, APKG_COL).
// Do not edit by hand: Anki imports compare against these exact collection defaults.
export const APKG_SCHEMA = ${JSON.stringify(read("genanki-schema.sql"))};
export const APKG_COL = ${JSON.stringify(read("genanki-col.sql"))};
`;
const target = fileURLToPath(new URL("app/src/export/genankiSql.ts", root));
writeFileSync(target, output);
console.log(`wrote ${target}`);
